declare
  row_old jsonb := case when tg_op in (''UPDATE'', ''DELETE'') then to_jsonb(old) end;
  row_new jsonb := case when tg_op in (''INSERT'', ''UPDATE'') then to_jsonb(new) end;
  target jsonb := coalesce(row_new, row_old);
  kind text := coalesce(nullif(current_setting(''transpera.actor_kind'', true), ''''), ''user'');
begin
  if tg_op = ''UPDATE'' and row_old - ''updated_at'' = row_new - ''updated_at'' then
    return null;
  end if;
  insert into public.audit_log (workspace_id, actor_id, actor_kind, action, target_table, target_id, diff)
  values (
    (target ->> ''workspace_id'')::uuid,
    auth.uid(),
    case when auth.uid() is null and kind = ''user'' then ''system'' else kind end,
    lower(tg_op),
    tg_table_name,
    (target ->> ''id'')::uuid,
    jsonb_strip_nulls(jsonb_build_object(''old'', row_old, ''new'', row_new))
  );
  return null;
end;
$$;

create trigger audit after insert or update or delete on public.memberships
  for each row execute function public.audit_access_change();
create trigger audit after insert or update or delete on public.workspace_domains
  for each row execute function public.audit_access_change();
create trigger audit after insert or update or delete on public.workspace_access_emails
  for each row execute function public.audit_access_change();

-- ---------------------------------------------------------------------------
-- Resolution
-- ---------------------------------------------------------------------------

-- True when the user signed in with a Google account managed by `domain`:
-- the ID token''s hosted-domain claim, which Supabase Auth stores as
-- identity_data.custom_claims.hd on the Google identity, equals the domain,
-- and so does the user''s confirmed email. Personal Google accounts have no
-- `hd`, so they never qualify. auth.identities is written only by Supabase
-- Auth; user_metadata is editable by the user and must not be trusted here.
create function public.qualifies_for_domain(uid uuid, domain text) returns boolean
language sql stable security definer
set search_path = ''''
as $$
  select exists (
    select 1
    from auth.users u
    join auth.identities i on i.user_id = u.id and i.provider = ''google''
    where u.id = uid
      and u.email_confirmed_at is not null
      and lower(split_part(u.email, ''@'', 2)) = domain
      and lower(i.identity_data -> ''custom_claims'' ->> ''hd'') = domain
  );
$$;

-- Brings one user''s memberships in line with the access lists. Idempotent.
-- Memberships with source ''manual'' are never touched; inactive ones are never
-- reactivated.
create function public.reconcile_access(uid uuid) returns void
language plpgsql security definer
set search_path = ''''
as $$
declare
  user_email text;
begin
  select lower(u.email) into user_email from auth.users u where u.id = uid and u.email_confirmed_at is not null;

  -- 1. Pre-assigned email: exactly the listed role (takes over a domain membership).
  insert into public.memberships as m (workspace_id, user_id, role, source, person_id)
  select e.workspace_id, uid, e.role, ''access_list'', e.person_id
  from public.workspace_access_emails e
  where user_email is not null and e.email = user_email
  on conflict (workspace_id, user_id) do update
    set role = excluded.role, source = ''access_list'', person_id = coalesce(excluded.person_id, m.person_id)
    where m.source <> ''manual''
      and (m.role, m.source, m.person_id) is distinct from
          (excluded.role, ''access_list'', coalesce(excluded.person_id, m.person_id));

  -- 2. Allowed domain: member, unless already a member some other way.
  insert into public.memberships (workspace_id, user_id, role, source)
  select d.workspace_id, uid, ''member'', ''domain''
  from public.workspace_domains d
  where public.qualifies_for_domain(uid, d.domain)
  on conflict (workspace_id, user_id) do nothing;

  -- 3a. Dropped from the list but still on an allowed domain: back to member.
  update public.memberships m
  set source = ''domain'', role = ''member''
  where m.user_id = uid and m.source = ''access_list''
    and not exists (
      select 1 from public.workspace_access_emails e
      where e.workspace_id = m.workspace_id and e.email = user_email)
    and exists (
      select 1 from public.workspace_domains d
      where d.workspace_id = m.workspace_id and public.qualifies_for_domain(uid, d.domain));

  -- 3b. No basis left: remove. Inactive domain memberships stay as a block.
  delete from public.memberships m
  where m.user_id = uid
    and (
      (m.source = ''access_list'' and not exists (
        select 1 from public.workspace_access_emails e
        where e.workspace_id = m.workspace_id and e.email = user_email))
      or (m.source = ''domain'' and m.active and not exists (
        select 1 from public.workspace_domains d
        where d.workspace_id = m.workspace_id and public.qualifies_for_domain(uid, d.domain)))
    );
end;
$$;

-- Called by the app after every sign-in (and when a signed-in user has no
-- workspace). Resolves the caller only, and returns their active memberships.
create function public.resolve_my_access()
returns table (workspace_id uuid, role public.membership_role, source text)
language plpgsql security definer
set search_path = ''''
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception ''not signed in'' using errcode = ''42501'';
  end if;
  perform set_config(''transpera.actor_kind'', ''system'', true);
  perform public.reconcile_access(uid);
  perform set_config(''transpera.actor_kind'', '''', true);
  return query
    select m.workspace_id, m.role, m.source from public.memberships m where m.user_id = uid and m.active;
end;
$$;

-- List and domain edits apply to affected users immediately, so removal takes
-- effect on their next request rather than their next sign-in.
create function public.reconcile_after_access_change() returns trigger
language plpgsql security definer
set search_path = ''''
as $$
declare
  uid uuid;
  ws uuid := coalesce(case when tg_op <> ''DELETE'' then new.workspace_id end, old.workspace_id);
begin
  if tg_table_name = ''workspace_access_emails'' then
    for uid in
      select u.id from auth.users u
      where lower(u.email) in (
        case when tg_op <> ''DELETE'' then new.email end,
        case when tg_op <> ''INSERT'' then old.email end)
    loop
      perform public.reconcile_access(uid);
    end loop;
  else
    for uid in
      select u.id from auth.users u
      where lower(split_part(u.email, ''@'', 2)) in (
        case when tg_op <> ''DELETE'' then new.domain end,
        case when tg_op <> ''INSERT'' then old.domain end)
      union
      select m.user_id from public.memberships m where m.workspace_id = ws and m.source = ''domain''
    loop
      perform public.reconcile_access(uid);
    end loop;
  end if;
  return null;
end;
$$;

create trigger reconcile after insert or update or delete on public.workspace_access_emails
  for each row execute function public.reconcile_after_access_change();
create trigger reconcile after insert or update or delete on public.workspace_domains
  for each row execute function public.reconcile_after_access_change();

-- Members of a workspace with their email and last sign-in, for the Access
-- page. auth.users is not readable by clients, so this is SECURITY DEFINER
-- and returns nothing unless the caller manages the workspace.
create function public.workspace_members(ws uuid)
returns table (
  membership_id uuid,
  user_id uuid,
  email text,
  role public.membership_role,
  source text,
  active boolean,
  person_id uuid,
  last_sign_in_at timestamptz,
  created_at timestamptz
)
language sql stable security definer
set search_path = ''''
as $$
  select m.id, m.user_id, u.email, m.role, m.source, m.active, m.person_id, u.last_sign_in_at, m.created_at
  from public.memberships m
  join auth.users u on u.id = m.user_id
  where m.workspace_id = ws and public.can_manage_workspace(ws)
  order by u.email;
$$;

-- Functions are executable by PUBLIC by default; expose only the two entry points.
revoke execute on function public.qualifies_for_domain(uuid, text) from public, anon, authenticated;
revoke execute on function public.reconcile_access(uuid) from public, anon, authenticated;
revoke execute on function public.resolve_my_access() from public, anon;
revoke execute on function public.workspace_members(uuid) from public, anon;
grant execute on function public.resolve_my_access() to authenticated;
grant execute on function public.workspace_members(uuid) to authenticated;
']);

-- 20260930040000_api_tokens.sql
-- Personal API tokens for the MCP server (docs/PRD.md §5, §7.1, §10; decision D12;
-- docs/adr/0002-mcp-acts-as-user-via-pre-request.md).
--
-- A token is shown to its owner once; only its SHA-256 hash is stored. A Data
-- API request that carries the token in the `x-api-token` header is switched,
-- by a PostgREST pre-request function, from `anon` to `authenticated` with the
-- token owner's claims, so every query runs as that user under RLS. The MCP
-- endpoint never uses the service-role key.

-- ---------------------------------------------------------------------------
-- Table
-- ---------------------------------------------------------------------------

create table public.api_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- Lowercase hex SHA-256 of the token; the token itself is never stored.
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  label text not null check (char_length(label) between 1 and 100),
  -- The MCP session's active workspace (set_active_workspace). Stored per
  -- token because the endpoint is stateless across serverless instances.
  active_workspace_id uuid references public.workspaces (id) on delete set null,
  last_used_at timestamptz,
  revoked_at timestamptz,
  -- Fixed one-minute window for per-token rate limiting (use_api_token).
  rate_window_start timestamptz,
  rate_window_count integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users (id) on delete set null default auth.uid()
);

create index on public.api_tokens (user_id);

create trigger set_updated_at before update on public.api_tokens for each row execute function public.set_updated_at();

-- Revoking is permanent.
create function public.api_tokens_keep_revoked() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'A revoked API token cannot be restored';
  end if;
  return new;
end;
$$;

create trigger keep_revoked before update on public.api_tokens
  for each row execute function public.api_tokens_keep_revoked();

-- Users see and manage only their own tokens. Column grants keep the hash and
-- the rate-limit counters out of reach of updates.
alter table public.api_tokens enable row level security;

create policy "read own api tokens" on public.api_tokens for select to authenticated
  using (user_id = auth.uid());
create policy "create own api tokens" on public.api_tokens for insert to authenticated
  with check (user_id = auth.uid() and revoked_at is null);
create policy "update own api tokens" on public.api_tokens for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

revoke all on public.api_tokens from anon, authenticated;
grant select on public.api_tokens to authenticated;
grant insert (label, token_hash) on public.api_tokens to authenticated;
grant update (label, revoked_at, active_workspace_id) on public.api_tokens to authenticated;

-- ---------------------------------------------------------------------------
-- Token resolution. `private` is not an API-exposed schema.
-- ---------------------------------------------------------------------------

create schema if not exists private;
grant usage on schema private to anon, authenticated, service_role;

create function private.hash_api_token(token text) returns text
language sql immutable
set search_path = ''
as $$
  select encode(pg_catalog.sha256(pg_catalog.convert_to(token, 'UTF8')), 'hex');
$$;

-- The owner's JWT claims for a live token, or null. Security definer because
-- `anon` cannot read api_tokens or auth.users; it resolves exactly one token
-- and nothing else.
create function private.api_token_claims(token text) returns jsonb
language sql stable security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'sub', u.id,
    'role', 'authenticated',
    'aud', 'authenticated',
    'email', u.email,
    'app_metadata', coalesce(u.raw_app_meta_data, '{}'::jsonb),
    'api_token_id', t.id
  )
  from public.api_tokens t
  join auth.users u on u.id = t.user_id
  where t.token_hash = private.hash_api_token(token)
    and t.revoked_at is null
    and (u.banned_until is null or u.banned_until <= now());
$$;

revoke all on function private.hash_api_token(text) from public;
revoke all on function private.api_token_claims(text) from public;
grant execute on function private.api_token_claims(text) to anon;

-- PostgREST pre-request hook: runs before every Data API request, after
-- PostgREST has set the role and claims from the request's JWT.
--
-- No header: nothing changes. With `x-api-token` on an anonymous request, a
-- live token switches the transaction to `authenticated` with its owner's
-- claims; anything else is rejected with 401.
--
-- Deliberately NOT security definer and without a `set` clause: Postgres
-- forbids SET ROLE in security-definer functions, and a function-level `set`
-- would undo the transaction-local settings when the function returns. SET
-- ROLE is checked against the session user (PostgREST's `authenticator`, a
-- member of `authenticated`), so it works from `anon`. Every name is
-- schema-qualified instead of relying on search_path.
create function private.api_token_pre_request() returns void
language plpgsql
as $$
declare
  token text := nullif(pg_catalog.current_setting('request.headers', true), '')::json ->> 'x-api-token';
  claims jsonb;
begin
  if token is null then
    return;
  end if;
  if current_user <> 'anon' then
    raise sqlstate 'PGRST' using
      message = json_build_object('code', 'API_TOKEN', 'message', 'Send either a session or an API token, not both')::text,
      detail = json_build_object('status', 400, 'headers', json_build_object())::text;
  end if;
  claims := private.api_token_claims(token);
  if claims is null then
    raise sqlstate 'PGRST' using
      message = json_build_object('code', 'API_TOKEN', 'message', 'Invalid or revoked API token')::text,
      detail = json_build_object('status', 401, 'headers', json_build_object('WWW-Authenticate', 'Bearer'))::text;
  end if;
  perform pg_catalog.set_config('request.jwt.claims', claims::text, true);
  set local role authenticated;
end;
$$;

-- Every request runs the hook, whatever its role.
revoke all on function private.api_token_pre_request() from public;
grant execute on function private.api_token_pre_request() to anon, authenticated, service_role;

-- Register the hook. `authenticator` exists on Supabase (and in the CI
-- PostgREST test), not in the plain-Postgres test databases.
do $$
begin
  if exists (select from pg_roles where rolname = 'authenticator')
     and not exists (
       select from pg_db_role_setting s join pg_roles r on r.oid = s.setrole
       where r.rolname = 'authenticator' and s.setdatabase = 0
         and 'pgrst.db_pre_request=private.api_token_pre_request' = any (s.setconfig)
     ) then
    alter role authenticator set pgrst.db_pre_request = 'private.api_token_pre_request';
  end if;
end;
$$;

notify pgrst, 'reload config';

-- ---------------------------------------------------------------------------
-- Per-request bookkeeping for the MCP endpoint: validates the token, records
-- last use and enforces the per-token rate limit (fixed one-minute window).
-- Called over the Data API with POST, so it may write (GET runs read-only).
-- `acting_as_user` reports whether the pre-request hook switched the caller to
-- the token's user, so the endpoint can refuse to run if the hook is missing.
-- ---------------------------------------------------------------------------

create function public.use_api_token(token text) returns jsonb
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  t public.api_tokens;
begin
  update public.api_tokens a
  set last_used_at = now(),
      rate_window_start = case when a.rate_window_start is null or a.rate_window_start <= now() - interval '1 minute'
                               then now() else a.rate_window_start end,
      rate_window_count = case when a.rate_window_start is null or a.rate_window_start <= now() - interval '1 minute'
                               then 1 else a.rate_window_count + 1 end
  where a.token_hash = private.hash_api_token(token) and a.revoked_at is null
  returning a.* into t;

  if not found then
    raise sqlstate 'PGRST' using
      message = json_build_object('code', 'API_TOKEN', 'message', 'Invalid or revoked API token')::text,
      detail = json_build_object('status', 401, 'headers', json_build_object())::text;
  end if;

  return jsonb_build_object(
    'allowed', t.rate_window_count <= 120,
    'retry_after_seconds', greatest(0, ceil(extract(epoch from (t.rate_window_start + interval '1 minute' - now()))))::integer,
    'active_workspace_id', t.active_workspace_id,
    'acting_as_user', auth.uid() is not distinct from t.user_id
  );
end;
$$;

revoke all on function public.use_api_token(text) from public;
grant execute on function public.use_api_token(text) to anon, authenticated;

